import { useEffect, useState } from 'react';
import {
  fetchWatchedFolders,
  createWatchedFolder,
  deleteWatchedFolder,
} from '../api/SettingApi';

export function useWatchedFolders() {
  const [folders, setFolders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refresh = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await fetchWatchedFolders();
      const list = Array.isArray(data) ? data : (data?.items ?? []);
      setFolders(
        list.map((it) => ({
          id: it.id ?? it.folderId ?? it.path, // 백엔드 응답 형태가 달라도 최대한 맞춤
          name: it.name ?? it.folderName ?? '폴더',
          path: it.path,
        }))
      );
    } catch (e) {
      setError(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refresh();
  }, []);

  const promptAndAddFolder = async () => {
    const path = window.prompt('감시 폴더 경로를 입력하세요');
    if (!path) return;

    const name = window.prompt('폴더 이름(표시용)을 입력하세요') || '폴더';
    await createWatchedFolder({ name, path });
    await refresh();
  };

  const removeFolder = async (id) => {
    await deleteWatchedFolder(id);
    await refresh();
  };

  return { folders, loading, error, refresh, promptAndAddFolder, removeFolder };
}
